import numpy as np, sys
def read(p):
    L=open(p).read().splitlines()
    n=int(L[0]); syms=[]; xyz=[]
    for line in L[2:2+n]:
        t=line.split(); syms.append(t[0]); xyz.append([float(x) for x in t[1:4]])
    return syms, np.array(xyz)
s,p = read(sys.argv[1] if len(sys.argv)>1 else "opt1.xyz")
def d(a,b): return np.linalg.norm(p[a]-p[b])
print("Au-Ge1 %.2f Au-Ge2 %.2f"%(d(0,1),d(0,28)))
for g,ns in [(1,[2,15,10,23]),(28,[29,42,37,50])]:
    print("Ge%d"%g, ["%s%d %.2f"%(s[j],j,d(g,j)) for j in ns])
# min interatomic distances sanity
n=len(s)
bad=[]
for i in range(n):
    for j in range(i+1,n):
        dd=d(i,j)
        if dd<0.9: bad.append((i,s[i],j,s[j],round(dd,2)))
print("too close:", bad[:10])
EOF
python3 check.py opt1.xyz
